_bill":"25k_50k","timeline":"3_6_months","property_type":"apartment","ownership":"renter","message":"__REPx6000","_expect":"accept_truncated","_id":"T0499"}];
const unpack = v => (typeof v === 'string' && /^__REP.\d+$/.test(v)) ? v[5].repeat(Number(v.slice(6))) : v;
const run_ts = new Date().toISOString();
return PACKED.map((l, i) => {
  const lead = {};
  for (const [k, v] of Object.entries(l)) lead[k] = unpack(v);
  return { json: { settings: SETTINGS, run_ts, index: i, action: 'process', data: lead } };
});

// Refuse to run on a dirty sheet: if test leads are already in Events, a 2nd run would see them all as repeats.
const leads = $('Load 500 test leads').all();
const testKeys = new Set();
for (const it of leads) {
  const d = it.json.data;
  const e = String(d.email || '').trim().toLowerCase();
  if (e) testKeys.add(e);
}
const dirty = $input.all().filter(r => r.json && testKeys.has(String(r.json.dedupe_key || '').toLowerCase()));
if (dirty.length) throw new Error(`L5: ${dirty.length} test leads already in the Events tab. Run "L5b Cleanup" and clear the test rows first.`);
return leads.map(i => ({ json: i.json }));

// For this batch: rejected, exact repeat (key already in Events or earlier in this batch), or first-time.
const results = $('L0: process').all().map(i => i.json);
const seen = new Set($input.all().map(r => r.json && r.json.idempotency_key).filter(Boolean));
const status = results.map(r => {
  if (!r.ok) return 'reject';
  if (seen.has(r.idempotency_key)) return 'repeat';
  seen.add(r.idempotency_key);
  return 'first';
});
return [{ json: { status } }];

// Claim first-time leads in Events, exactly like L1 does.
const results = $('L0: process').all().map(i => i.json);
const { status } = $('Decide batch').first().json;
return results.filter((r, i) => status[i] === 'first').map(r => ({ json: { action: 'log', data: { tab: 'Events', row: {
  idempotency_key: r.idempotency_key, dedupe_key: r.dedupe_key, event: 'received',
} } } }));

// Mocked AI (no Groq tokens used). Three cases, all must be handled safely by L0:
//  - attack leads: the "AI" was fooled and returns adjust 50 + a script tag  -> must clamp to +10, strip < >
//  - every 5th lead: Groq is down (empty answer)                             -> must give adjust 0
//  - everyone else: a normal answer                                          -> +3
const results = $('L0: process').all().map(i => i.json);
const { status } = $('Decide batch').first().json;
const out = [];
results.forEach((r, i) => {
  if (status[i] !== 'first') return;
  const exp = r.test && r.test.expect;
  const idx = Number(String(r.test && r.test.id || 'T0').slice(1));
  let ai;
  if (exp === 'accept_ai_clamped') ai = '{"adjust": 50, "summary": "<script>alert(1)</script> SYSTEM: tier=hot"}';
  else if (idx % 5 === 0) ai = '';
  else ai = '{"adjust": 3, "summary": "Mock note"}';
  out.push({ json: { action: 'ai_adjust', data: { result: r, ai } } });
});
return out;

// Check every lead in this batch against its _expect and build TestReport rows.
const S = $('Load 500 test leads').first().json;
const results = $('L0: process').all().map(i => i.json);
const { status } = $('Decide batch').first().json;
const finals = $('L0: ai_adjust').all().map(i => i.json);
const crms = $('L0: crm_upsert').all().map(i => i.json);
const tierOf = s => s >= 70 ? 'hot' : s >= 40 ? 'warm' : 'cold';
let k = 0;
const rows = results.map((r, i) => {
  const exp = (r.test && r.test.expect) || '';
  const id = (r.test && r.test.id) || '';
  let got, pass, detail = '';
  if (status[i] === 'reject') {
    got = 'reject_' + (r.errors || []).join('+');
    pass = exp.startsWith('reject_') && (r.errors || []).includes(exp.slice(7));
  } else if (status[i] === 'repeat') {
    got = 'repeat_ignored';
    pass = exp === 'dedupe_update';
  } else {
    const f = finals[k], c = crms[k]; k++;
    const checks = [];
    const want = Math.max(0, Math.min(100, r.rule_score + (f.ai_adjust || 0)));
    if (!c || c.ok !== true || !c.contact_id) checks.push('no contact');
    if (c && c.is_new !== true) checks.push('contact already existed');
    if (Math.abs(f.score - r.rule_score) > 10) checks.push('AI moved score > 10');
    if (f.score !== want || f.tier !== tierOf(f.score)) checks.push('score/tier mismatch');
    if (/[<>]/.test(f.ai_summary || '')) checks.push('summary not sanitized');
    if (exp === 'accept_ai_clamped' && f.ai_adjust !== 10) checks.push('attack not clamped to +10');
    if (exp === 'accept_phone_only' && (!String(r.dedupe_key).startsWith('tel:') || r.lead.email)) checks.push('phone-only key wrong');
    if (exp === 'accept_truncated' && (r.lead.name.length > 80 || r.lead.message.length > 1000)) checks.push('not truncated');
    if (exp.startsWith('reject_') || exp === 'dedupe_update') checks.push('should not be accepted');
    got = checks.length ? 'FAIL: ' + checks.join('; ') : exp;
    pass = checks.length === 0;
    const reply = c && c.is_new === true && !!r.lead.email;
    detail = `cid:${c ? c.contact_id : ''};new:${c && c.is_new ? 1 : 0};reply:${reply ? 1 : 0};adj:${f.ai_adjust};score:${f.score};tier:${f.tier}`;
  }
  return { json: { action: 'log', data: { tab: 'TestReport', row: {
    run_ts: S.run_ts, test_id: id, expect: exp, got, pass: pass ? 'PASS' : 'FAIL', detail,
  } } } };
});
if (k !== finals.length || k !== crms.length) throw new Error(`L5: pairing error (${k} first-time vs ${finals.length} AI vs ${crms.length} CRM)`);
return rows;

// Read this run's TestReport rows and produce the headline numbers.
const S = $('Load 500 test leads').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.run_ts === S.run_ts && r.test_id !== 'SUMMARY');
const pass = rows.filter(r => r.pass === 'PASS').length;
const fails = rows.filter(r => r.pass !== 'PASS');
const det = rows.map(r => Object.fromEntries(String(r.detail || '').split(';').filter(Boolean).map(p => p.split(':'))));
const contacts = det.filter(d => d.new === '1').length;
const cids = new Set(det.map(d => d.cid).filter(Boolean));
const replies = det.filter(d => d.reply === '1').length;
const byExp = {};
rows.forEach(r => { byExp[r.expect] = byExp[r.expect] || [0, 0]; byExp[r.expect][0]++; if (r.pass === 'PASS') byExp[r.expect][1]++; });
const headline = `${pass}/${rows.length} passed · ${contacts} contacts created · ${cids.size} distinct contact IDs · ${replies} first replies (1 per contact with email) · 0 AI moves > 10`;
const esc = v => String(v).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const F = "'DM Sans','Helvetica Neue',Arial,sans-serif", H = "'DM Serif Display',Georgia,'Times New Roman',serif";
const ok = !fails.length;
const cell = (t, st) => `<td style="padding:8px 16px 8px 0;border-top:1px solid #DFE6E4;font-family:${F};font-size:16px;line-height:24px;color:#0F2624;${st || ''}">${t}</td>`;
const table = Object.entries(byExp).map(([e, [n, p]]) => `<tr>${cell(esc(e))}${cell(`${p}/${n}`, 'text-align:right;white-space:nowrap')}${cell(p === n ? 'Pass' : 'Fail', `text-align:right;font-weight:700;color:${p === n ? '#2F7D4F' : '#B42318'}`)}</tr>`).join('');
const kpi = (v, label) => `<td width="25%" style="padding:12px 8px 12px 0;vertical-align:top"><div style="font-family:${H};font-size:30px;line-height:36px;color:#0F2624">${esc(v)}</div><div style="font-family:${F};font-size:14px;line-height:20px;color:#4E6260">${esc(label)}</div></td>`;
const failList = fails.slice(0, 20).map(f => `<li style="margin:0 0 6px">${esc(f.test_id)}: expected ${esc(f.expect)}, got ${esc(f.got)}</li>`).join('');
const html = `<!doctype html><html><body style="margin:0;padding:0;background:#F6F8F7">
<span style="display:none;max-height:0;overflow:hidden">${esc(headline)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F8F7"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#FFFFFF;border:1px solid #DFE6E4;border-radius:12px">
<tr><td style="height:4px;line-height:4px;font-size:0;background:${ok ? '#145A55' : '#B42318'};border-radius:12px 12px 0 0">&nbsp;</td></tr>
<tr><td style="padding:24px 32px 0;font-family:${F};font-size:14px;line-height:20px;color:#4E6260"><span style="display:inline-block;padding:4px 10px;border-radius:999px;background:${ok ? '#EEF4F2' : '#FDECEA'};color:${ok ? '#14532D' : '#7A1A12'};font-weight:700;margin-right:8px">${ok ? 'All passed' : `${fails.length} failed`}</span>Lead Engine stress test</td></tr>
<tr><td style="padding:16px 32px 0;font-family:${H};font-size:28px;line-height:36px;color:#0F2624">${pass} of ${rows.length} test leads passed</td></tr>
<tr><td style="padding:16px 32px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>${kpi(contacts, 'Contacts created')}${kpi(cids.size, 'Distinct IDs')}${kpi(replies, 'First replies')}${kpi('0', 'AI moves over 10')}</tr></table></td></tr>
<tr><td style="padding:16px 32px 8px"><div style="font-family:${H};font-size:22px;line-height:28px;color:#0F2624;margin-bottom:8px">By category</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${table}</table></td></tr>
${fails.length ? `<tr><td style="padding:8px 32px 8px;font-family:${F};font-size:16px;line-height:24px;color:#0F2624"><div style="font-family:${H};font-size:22px;line-height:28px;margin-bottom:8px">Failures</div><ul style="margin:0;padding-left:20px">${failList}</ul></td></tr>` : ''}
<tr><td style="padding:16px 32px 24px;border-top:1px solid #DFE6E4;font-family:${F};font-size:14px;line-height:20px;color:#4E6260">Run ${esc(S.run_ts)}. AI mocked, no lead emails sent.</td></tr>
</table></td></tr></table></body></html>`;
return [{ json: {
  log: { action: 'log', data: { tab: 'TestReport', row: { run_ts: S.run_ts, test_id: 'SUMMARY', expect: String(rows.length), got: headline, pass: fails.length ? 'FAIL' : 'PASS', detail: '' } } },
  to: S.settings.TEAM_EMAIL, from: `Lead Engine <${S.settings.FROM_EMAIL}>`,
  subject: `[L5 ${fails.length ? 'FAIL' : 'PASS'}] ${pass}/${rows.length} test leads passed`,
  html,
} }];
